   * const message = useValidationMessage(); // из '@reformer/core/i18n'
   *
   * return (
   *   <ul className="error-list">
   *     {errors.map((error, i) => (
   *       <li key={i}>{message(error)}</li>
   *     ))}
   *   </ul>
   * );
   * ```
   */
  errors: ValidationError[];

